    pub fn restarted(&mut self) {
        self.close_approval();
        if matches!(
            self.overlay,
            Some(Overlay::Detail(_) | Overlay::Receipt(_) | Overlay::Models(_) | Overlay::Connect(_) | Overlay::Review(_))
        ) {
            self.overlay = None;
        }
        // Evidence ids are numbered per sidecar process; the new one would answer for other calls.
        for entry in &mut self.transcript {
            match entry {
                Entry::Tool { evidence, diff, .. } => {
                    evidence.clear();
                    if let Some(card) = diff {
                        card.evidence.clear();
                    }
                }
                Entry::Diff { card, .. } => card.evidence.clear(),
                _ => {}
            }
        }
        // The new sidecar generates its own session id and has persisted nothing under it yet.
        self.session_saved = false;
        self.link = Link::Connecting;
        self.session.busy = false;
        self.cancel_requested = false;
        self.cancel_started = None;
        self.transcript.push(Entry::Notice(
            "Started a new agent sidecar. It does not remember the conversation above.".to_string(),
        ));
    }

    pub fn on_paste(&mut self, text: &str) {
        if matches!(self.overlay, Some(Overlay::Paste { .. })) {
            return;
        }
        match &mut self.overlay {
            Some(Overlay::Connect(flow)) => return flow.on_paste(text),
    pub fn handle(&mut self, action: Action) -> bool {
        match action {
            Action::Send(command) => {
                if let Some(sidecar) = self.sidecar.as_mut() {
                    if matches!(command, Command::PromptSubmit { .. }) {
                        sidecar.forget_stderr();
                    }
                    // A failed write means the child is gone; its Closed message reports that.
                    let _ = sidecar.send(&command);
                }
                true
            }
            Action::Quit => {
                if let Some(sidecar) = self.sidecar.take() {
                    sidecar.shutdown(SHUTDOWN_GRACE);
                }
                false
            }
            Action::Restart => {
                if let Some(mut sidecar) = self.sidecar.take() {
                    sidecar.reap(Duration::ZERO);
                }
                self.state.restarted();
                self.spawn();
                true
            }
        }
    }
}

/// Restores the terminal on every exit path. ratatui's panic hook restores raw mode and the alternate screen
/// but not bracketed paste or the keyboard protocol, so those are undone here, during unwinding as well.
struct TerminalGuard {
    keyboard_protocol: bool,
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        if self.keyboard_protocol {
            let _ = execute!(io::stdout(), PopKeyboardEnhancementFlags);
        }
        let _ = execute!(io::stdout(), DisableBracketedPaste);
        ratatui::restore();
    }
}

pub fn run_live(spec: SidecarSpec) -> Result<(), Box<dyn std::error::Error>> {
    install_stop_signals();
    spawn_stop_watchdog();
    let mut guard = TerminalGuard {
        keyboard_protocol: false,
    };
